import { MeshStandardNodeMaterial } from 'three/webgpu';
import { color, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Color } = ctx.THREE;

  // 1. Root group
  const group = new Group();
  group.position.set(0, 1, 0.06);

  // Keep track of GSAP timelines for cleanup
  const activeTimelines = [];
  const activePrimitives = [];

  // Colors
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. Base Platform Frame (Interactive Card Panel)
  // Dimensions fitting a sleek label inside the design rhythm (base unit 0.25)
  const cardWidth = 2.0;
  const cardHeight = 0.8;

  // Background Panel
  const panelGeo = new PlaneGeometry(cardWidth, cardHeight);
  const panelMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.5,
    metalness: 0.55,
    transparent: true,
    opacity: 0.95
  });

  const panelMesh = new Mesh(panelGeo, panelMat);
  group.add(panelMesh);

  // Accent Edge Line (Laser Red Active Border)
  const borderGeo = new PlaneGeometry(cardWidth + 0.03, 0.02);
  const borderMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    roughness: 0.2,
    metalness: 0.9,
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.2
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.set(0, -cardHeight / 2, 0.01);
  group.add(borderMesh);

  // 3. Load Rich Texture Mapping
  const finalImageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  ctx.textureLoader.loadTexture(finalImageUrl).then((tex) => {
    panelMat.map = tex;
    panelMat.needsUpdate = true;
  }).catch(() => {
    // Graceful fallback to flat procedural styling
  });

  // 4. Local Product-Shot Lighting Setup
  const localRimLight = new DirectionalLight(colors.accent, 0.7);
  localRimLight.position.set(-2, 1.5, 2);
  group.add(localRimLight);

  // 5. Render Verbatim Typography
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const primaryText = textItems.find(t => t.text)?.text || "Journal 2";

  const textMesh = ctx.fontAtlas.createText(primaryText, {
    fontSize: 0.16, // Proportional text scale (13px equivalent in scene metrics)
    color: colors.paper,
    align: 'center'
  });
  textMesh.position.set(0, 0, 0.03);
  group.add(textMesh);

  // 6. Interactive Animation Vocabulary (GSAP Presets)
  let currentY = group.position.y;
  let currentZ = group.position.z;

  const onHoverStart = () => {
    const hoverTL = gsap.timeline();
    // Subtle rise-in lift (0.15 scene units) & slight tilt
    hoverTL.to(group.position, {
      y: currentY + 0.15,
      z: currentZ + 0.05,
      duration: 0.4,
      ease: 'power3.out'
    });
    // Edge glow bloom
    hoverTL.to(borderMat, {
      emissiveIntensity: 2.2,
      duration: 0.3
    }, 0);
    activeTimelines.push(hoverTL);
  };

  const onHoverEnd = () => {
    const settleTL = gsap.timeline();
    // Settle overshoot back to default placement
    settleTL.to(group.position, {
      y: currentY,
      z: currentZ,
      duration: 0.6,
      ease: 'power4.out'
    });
    settleTL.to(borderMat, {
      emissiveIntensity: 1.2,
      duration: 0.4
    }, 0);
    activeTimelines.push(settleTL);
  };

  const onClick = () => {
    const pressTL = gsap.timeline();
    // Weighted-settle style dynamic squash on press
    pressTL.to(group.scale, {
      x: 0.95,
      y: 0.95,
      z: 0.95,
      duration: 0.12,
      ease: 'back.out(2)'
    });
    pressTL.to(group.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.4,
      ease: 'power3.out'
    });

    activeTimelines.push(pressTL);

    // Dynamic state reporting & mutation routes triggers
    ctx.emit('hub-journal.select', {
      itemId: 'journal-2-label',
      meta: { timestamp: new Date().toISOString() }
    });
  };

  // Attach internal event pointers using the standard runtime system
  group.userData.handlers = {
    pointerover: onHoverStart,
    pointerout: onHoverEnd,
    click: onClick
  };

  // 7. Cinematic Primitives Binding
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives[primitive.name]) {
        const primRef = ctx.primitives[primitive.name](group, primitive.params);
        if (primRef) activePrimitives.push(primRef);
      }
    });
  } else {
    // Standard Fallback: Parallax-scroll (intensity: 0.25)
    if (ctx.primitives['parallax-scroll']) {
      const primRef = ctx.primitives['parallax-scroll'](group, { intensity: 0.25 });
      if (primRef) activePrimitives.push(primRef);
    }
  }

  // 8. Dynamic Cleanup Routine
  group.userData.cleanup = function () {
    activeTimelines.forEach((tl) => tl.kill());
    activePrimitives.forEach((prim) => {
      if (typeof prim.cleanup === 'function') prim.cleanup();
    });
    panelGeo.dispose();
    panelMat.dispose();
    borderGeo.dispose();
    borderMat.dispose();
    localRimLight.dispose();
  };

  return group;
}
